// Group the login password-masking scenario.
describe('Swag Labs authentication', () => {
  // Define the single password-masking scenario.
  it('masks the typed password on the login page', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Type the password into the password input.
    cy.get('[data-test="password"]').type('secret_sauce');

    // Confirm the input uses password masking.
    cy.get('[data-test="password"]').should('have.attr', 'type', 'password');
    // Confirm the input retains the typed password value.
    cy.get('[data-test="password"]').should('have.value', 'secret_sauce');
  });
});
